pub struct DesktopApp<M: DesktopViewModel, H: microts::Host = microts::CoreHost> {
    pub host: H,
    pub model: M,
    props: DesktopProps,
    view: DesktopView,
    invalidation: microts::Invalidation,
    events: alloc::vec::Vec<DesktopEvent>,
}

impl<M: DesktopViewModel, H: microts::Host> DesktopApp<M, H> {
    pub fn new(mut host: H, props: DesktopProps, model: M) -> Self {
        let view =
            <DesktopView>::mount(host.ui_mut(), microts::NodeId::ROOT, microts::NodeId::NONE);
        Self {
            host,
            model,
            props,
            view,
            invalidation: microts::Invalidation::default(),
            events: alloc::vec::Vec::new(),
        }
    }

    pub fn frame(&mut self, input: &microts::Input) -> &[DesktopEvent] {
        self.events.clear();
        let input = self.host.ui_mut().resolve_input(input);
        let handled = self
            .view
            .dispatch(&input, &self.props, &mut self.model, &mut self.events);
        if handled {
            self.invalidation.invalidate();
        };
        if self.invalidation.take() {
            self.view
                .update(self.host.ui_mut(), &self.props, &self.model);
        };
        self.host.ui_mut().tick();
        self.events.as_slice()
    }

    pub fn invalidate(&mut self) {
        self.invalidation.invalidate();
    }

    pub fn set_props(&mut self, props: DesktopProps) {
        self.props = props;
        self.invalidation.invalidate();
    }

    pub fn unmount(mut self) -> microts::Ui {
        self.view.unmount(self.host.ui_mut());
        self.host.into_ui()
    }

    pub fn ui(&self) -> &microts::Ui {
        self.host.ui()
    }

    pub fn ui_mut(&mut self) -> &mut microts::Ui {
        self.host.ui_mut()
    }
}
